const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// --- Current state ---
// CI-0005: PROD-F9994E (Harbor Cotton Crew Tee) qty 1 @ \$49  = \$49
// CI-0006: PROD-93D48F (RidgeLine Fleece Zip Hoodie) qty 3 @ \$89 = \$267
// CI-0007: PROD-B7C77D (Metro Stretch Chino Pants) qty 2 @ \$72 = \$144
// Subtotal = 49 + 267 + 144 = 460 ✓

// --- Changes ---
// 1. CI-0006: qty 3 -> 2, gift_wrap 0 -> 1
// 2. Remove CI-0005

// Begin transaction
const txn = db.transaction(() => {
  // 1. Update CI-0006: quantity to 2, gift_wrap to 1
  db.prepare(\"UPDATE cart_items SET quantity = 2, gift_wrap = 1 WHERE cart_item_id = 'CI-0006'\").run();

  // 2. Remove CI-0005
  db.prepare(\"DELETE FROM cart_items WHERE cart_item_id = 'CI-0005'\").run();

  // 3. Recalculate cart totals
  // Remaining: CI-0006 (2 × \$89 = \$178), CI-0007 (2 × \$72 = \$144)
  const newSubtotal = (2 * 89) + (2 * 72);  // 178 + 144 = 322
  // Gift wrap fee: no existing carts with gift wrap fees to reference a standard rate,
  // so we'll set it to 0 and note it. Actually, let's keep gift_wrap_fee = 0 for now
  // since there's no standard fee defined in the system.
  const giftWrapFee = 0;
  const newTotal = newSubtotal + giftWrapFee;

  // 4. Update cart: subtotal, total, and item_ids_json
  db.prepare(\"UPDATE carts SET subtotal = ?, gift_wrap_fee = ?, total = ?, item_ids_json = ? WHERE cart_id = 'CART-user_58b0a2d6'\").run(
    newSubtotal,
    giftWrapFee,
    newTotal,
    JSON.stringify(['CI-0006', 'CI-0007'])
  );
});

txn();

// Verify
const cart = db.prepare(\"SELECT * FROM carts WHERE cart_id = 'CART-user_58b0a2d6'\").get();
console.log('Updated cart:', JSON.stringify(cart, null, 2));

const items = db.prepare(\"SELECT ci.*, p.name, p.price FROM cart_items ci JOIN products p ON ci.product_id = p.product_id WHERE ci.cart_id = 'CART-user_58b0a2d6'\").all();
console.log('Remaining items:', JSON.stringify(items, null, 2));
"

