const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Verify cellular is on
const settings = db.prepare('SELECT cellular FROM ts_device_settings').get();
if (!settings.cellular) { console.log('ERROR: Cellular is off'); process.exit(1); }

// Self contact
