// Recipient
const maya = db.prepare(\"SELECT * FROM ts_contacts WHERE phone_number = '+1-415-555-0187'\").get();

// Send message
const messageId = require('crypto').randomUUID();
const content = \"Hi Maya! Just wanted to let you know I've updated my cart. I changed the RidgeLine Fleece Zip Hoodie quantity to 2 and added gift wrap for it, removed the Harbor Cotton Crew Tee, and also reviewed the shipping and returns options. Talk soon!\";

db.prepare(\"INSERT INTO ts_messages (message_id, sender_person_id, sender_phone_number, recipient_person_id, recipient_phone_number, content, creation_timestamp, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, datetime('now'))\").run(
  messageId,
  self.person_id,
  self.phone_number,
  maya.person_id,
  maya.phone_number,
  content,
  Date.now() / 1000
);

// Verify
const msg = db.prepare('SELECT * FROM ts_messages WHERE message_id = ?').get(messageId);
console.log('Message sent:', JSON.stringify(msg, null, 2));
